package io.xeros.solo;
import io.xeros.*;import io.xeros.content.skills.*;import io.xeros.content.skills.mining.*;import io.xeros.content.skills.mining.CoreRockMining.Rock;import io.xeros.model.collisionmap.*;import io.xeros.model.entity.player.*;import java.util.*;import java.lang.reflect.*;import java.util.function.IntUnaryOperator;
public final class CoreRockMiningCheck {
 static void ok(boolean b,String why){if(!b)throw new AssertionError(why);}static void tick(int n){SkillsAuditCheck.tick(n);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void give(Player p,int id,int n){ok(p.getItems().addItem(id,n),"Fixture "+id);}
 static IntUnaryOperator success(int bonus){return b->b==256?0:b==100?bonus:b-1;}
 static List<WorldObject> nodes()throws Exception{
  Field f=RegionProvider.class.getDeclaredField("regions");f.setAccessible(true);Map<String,WorldObject> unique=new LinkedHashMap<>();
  for(Region region:((Map<Integer,Region>)f.get(RegionProvider.getGlobal())).values())for(WorldObject o:region.worldObjectsSnapshot()){
   ObjectDef def=ObjectDef.getObjectDef(o.id);if(CoreRockMining.rock(o.id)==null||(o.type!=10&&o.type!=11)||def.actions==null||!Arrays.asList(def.actions).contains("Mine"))continue;
   unique.putIfAbsent(o.x+":"+o.y+":"+o.height+":"+o.type,o);
  }return new ArrayList<>(unique.values());
 }
 static Player actor(WorldObject o){Player p=AttackDefencePlayableCheck.actor();p.absX=o.x-1;p.absY=o.y;p.heightLevel=o.height;give(p,1275,1);return p;}
 static WorldObject node(List<WorldObject> rows,Rock rock){return rows.stream().filter(o->CoreRockMining.rock(o.id)==rock&&!CoreRockMining.guild(o.x,o.y,o.height)).findFirst().orElseThrow();}
 static void restore(WorldObject o){Rock rock=CoreRockMining.rock(o.id);if(rock==Rock.ESSENCE)return;for(int i=0;i<CoreRockMining.respawn(rock,o.x,o.y,o.height);i++)Server.getGlobalObjects().pulse();ok(RegionProvider.getGlobal().get(o.x,o.y).getWorldObject(o.id,o.x,o.y,o.height).isPresent(),"Restore "+o);}
 static void xp(Player p,int before,double... amounts){Player reference=AttackDefencePlayableCheck.actor();int old=reference.playerXP[14];for(double amount:amounts)reference.getPA().addSkillXPMultiplied(amount,14,true);ok(p.playerXP[14]-before==reference.playerXP[14]-old,"Exact Mining XP actual="+(p.playerXP[14]-before)+" reference="+(reference.playerXP[14]-old)+" bonus="+Configuration.BONUS_SKILL);}
 static void tables(){
  int[][] expected={{1,5,128,400,2,741600},{1,175,100,350,4,741600},{1,175,100,350,4,741600},{15,350,96,350,9,741600},{20,400,25,200,100,741600},{30,500,16,100,50,290640},{40,650,7,75,100,296640},{55,800,4,50,200,148320},{70,950,2,25,400,59328},{85,1250,1,18,1200,42377},{1,50,256,256,0,0},{10,175,90,350,42,741600},{70,50,256,256,2,148320}};
  // Clay XP is five; the other references in this array use tenths.
  for(int i=0;i<Rock.values().length;i++){Rock r=Rock.values()[i];int[] e=expected[i];ok(r.level()==e[0]&&r.xp()==(i==0?5:e[1]/10d)&&r.low==e[2]&&r.high==e[3]&&r.respawn==e[4]&&r.petBase==e[5],"Frozen standard ore reference "+r);}
  ok(Mineral.forObjectId(11362)==Mineral.COPPER&&Mineral.forObjectId(11371)==Mineral.GOLD,"Missing standard variants");
  for(Rock r:Rock.values())for(int lvl:new int[]{1,15,30,55,70,85,99,110})for(int bonus:new int[]{0,4,7,11}){int v=Math.min(99,lvl)+bonus;int value=Math.max(0,Math.min(256,1+(int)Math.floor((r.low*(99d-v)+r.high*(v-1d))/98d+.5)));ok(CoreRockMining.threshold(r,lvl,bonus)==value,"Chance interpolation "+r);}
  Player p=AttackDefencePlayableCheck.actor();p.playerEquipment[Player.playerRing]=25539;p.absX=3020;p.absY=9700;ok(CoreRockMining.invisibleBoost(p)==11&&CoreRockMining.respawn(Rock.RUNITE,p.absX,p.absY,0)==600,"Guild boost and half respawn");p.heightLevel=1;ok(CoreRockMining.invisibleBoost(p)==4,"Guild height guard");
  p.playerEquipment[Player.playerHat]=12013;p.playerEquipment[Player.playerChest]=13107;p.playerEquipment[Player.playerLegs]=12015;p.playerEquipment[Player.playerFeet]=12016;ok(Math.abs(SkillingOutfit.PROSPECTOR.multiplier(p)-1.025)<.000001,"Varrock4 substitutes prospector top/full set");
  System.out.println("CORE_MINING_THIRTEEN_FROZEN_ORE_TABLES_416_CHANCE_CASES_MISSING_VARIANTS_GUILD_BOOST_RESPAWN_AND_VARROCK4_PROSPECTOR_OK");
 }
 static void cycles(List<WorldObject> rows){Map<Rock,Integer> totals=new EnumMap<>(Rock.class);Set<Integer> ids=new TreeSet<>();int tested=0;
  for(WorldObject o:rows){Rock rock=CoreRockMining.rock(o.id);Player p=actor(o);int before=p.playerXP[14],clip=p.getRegionProvider().getClipping(o.x,o.y,o.height);ok(CoreRockMining.start(p,o.id,o.x,o.y,success(99)),"Start native ore "+o);tick(2);ok(count(p,rock.item(p))==0,"Early rune-pick reward");tick(1);SkillsAuditCheck.clear(p);ok(count(p,rock.item(p))==1,"Ore output "+o);xp(p,before,rock.xp());
   if(rock!=Rock.ESSENCE){ok(Server.getGlobalObjects().exists(Mineral.EMPTY_VEIN,o.x,o.y,o.height),"One ore depletes "+o);ok(!CoreRockMining.start(actor(o),o.id,o.x,o.y,success(99)),"Already depleted ore accepted");int respawn=CoreRockMining.respawn(rock,o.x,o.y,o.height);for(int i=0;i<respawn-1;i++)Server.getGlobalObjects().pulse();ok(p.getRegionProvider().get(o.x,o.y).getWorldObject(o.id,o.x,o.y,o.height).isEmpty(),"Early respawn");Server.getGlobalObjects().pulse();ok(p.getRegionProvider().get(o.x,o.y).getWorldObject(o.id,o.x,o.y,o.height).isPresent(),"Exact respawn");ok(p.getRegionProvider().getClipping(o.x,o.y,o.height)==clip,"Collision after respawn "+o);}
   else ok(!Server.getGlobalObjects().exists(Mineral.EMPTY_VEIN,o.x,o.y,o.height),"Essence must not deplete");
   ids.add(o.id);totals.merge(rock,1,Integer::sum);tested++;
  }
  ok(tested>1400&&totals.size()==13,"World ore coverage "+totals);System.out.println("CORE_MINING_ALL_NATIVE_STANDARD_ROCKS_EXTRACTION_LEVEL99_XP_ONE_ORE_DEPLETE_EXACT_RESPAWN_COLLISION_AND_INFINITE_ESSENCE_OK count="+tested+" ids="+ids+" totals="+totals);
 }
 static void bonuses(List<WorldObject> rows){
  WorldObject iron=node(rows,Rock.IRON);for(int roll:new int[]{0,6,11}){Player p=actor(iron);p.playerEquipment[Player.playerChest]=13104;p.playerEquipment[Player.playerCape]=9792;int before=p.playerXP[14];CoreRockMining.start(p,iron.id,iron.x,iron.y,success(roll));tick(3);SkillsAuditCheck.clear(p);int expected=roll==0?3:roll==6?2:1;ok(count(p,440)==expected,"Independent cape5/armour10 probabilities "+roll);double[] awards=new double[expected];Arrays.fill(awards,35);xp(p,before,awards);restore(iron);}
  WorldObject rune=node(rows,Rock.RUNITE);for(int armour:new int[]{13106,13107}){Player p=actor(rune);p.playerEquipment[Player.playerChest]=armour;p.playerEquipment[Player.playerCape]=9792;CoreRockMining.start(p,rune.id,rune.x,rune.y,success(0));tick(3);SkillsAuditCheck.clear(p);ok(count(p,451)==(armour==13107?2:1),"Runite needs armour4; cape must not double rune");restore(rune);}
  for(Rock rock:Rock.values())for(int gloves:new int[]{21343,21345,21392}){Player p=AttackDefencePlayableCheck.actor();p.playerEquipment[Player.playerHands]=gloves;int denominator=CoreRockMining.gloveDenominator(p,rock);int got=0;for(int i=0;i<Math.max(1,denominator);i++){final int roll=i;if(CoreRockMining.gloveSave(p,rock,b->roll))got++;}ok(got==(denominator==0?0:rock==Rock.COAL?2:1),"Historical glove exact outcomes "+rock+gloves);if(rock==Rock.IRON||rock==Rock.COPPER||rock==Rock.TIN)ok(denominator==0,"2024 glove feature leaked into2022");}
  Player coal=actor(node(rows,Rock.COAL));coal.playerEquipment[Player.playerHands]=21343;WorldObject c=node(rows,Rock.COAL);CoreRockMining.start(coal,c.id,c.x,c.y,b->b==256?0:b==5?0:b-1);tick(3);SkillsAuditCheck.clear(coal);ok(count(coal,453)==1&&coal.getRegionProvider().get(c.x,c.y).getWorldObject(c.id,c.x,c.y,c.height).isPresent(),"2022 glove save keeps mining rock active");CoreRockMining.start(coal,c.id,c.x,c.y,b->b==256?0:b-1);tick(3);SkillsAuditCheck.clear(coal);ok(count(coal,453)==2&&Server.getGlobalObjects().exists(Mineral.EMPTY_VEIN,c.x,c.y,c.height),"Unsaved second ore depletes");restore(c);
  System.out.println("CORE_MINING_NATIVE_CAPE5_ARMOUR10_INDEPENDENT_BONUSES_EXTRA_XP_RUNE_LIMITS_AND_39_HISTORICAL_GLOVE_COMBINATIONS_OK");
 }
 static void guards(List<WorldObject> rows){
  WorldObject iron=node(rows,Rock.IRON);for(int mode=0;mode<7;mode++){Player p=actor(iron);int before=p.playerXP[14];if(mode==0){p.playerLevel[14]=14;ok(!CoreRockMining.start(p,iron.id,iron.x,iron.y,success(99)),"Level15 gate");continue;}ok(CoreRockMining.start(p,iron.id,iron.x,iron.y,success(99)),"Guard fixture");if(mode==1)p.absX++;if(mode==2)p.heightLevel++;if(mode==3)p.getItems().deleteItem2(1275,1);if(mode==4)p.interruptActions();if(mode==5)p.isDead=true;if(mode==6)while(p.getItems().freeSlots()>0)give(p,229,1);tick(6);SkillsAuditCheck.clear(p);ok(count(p,440)==0&&p.playerXP[14]==before,"Interrupted action gave ore/XP mode="+mode);}
  Player pre=actor(iron);int before=pre.playerXP[14];CoreRockMining.start(pre,iron.id,iron.x,iron.y,b->b==32768?70:b-1);tick(3);SkillsAuditCheck.clear(pre);ok(count(pre,1623)==1&&count(pre,440)==0&&pre.playerXP[14]==before&&!Server.getGlobalObjects().exists(Mineral.EMPTY_VEIN,iron.x,iron.y,iron.height),"Gem pre-roll must not give ore/XP/depletion");
  Player blank=actor(iron);CoreRockMining.start(blank,iron.id,iron.x,iron.y,b->b==32768?0:b-1);tick(3);SkillsAuditCheck.clear(blank);ok(count(blank,440)==0&&count(blank,1623)==0,"Empty gem-table result suppresses ore");
  Player pet=actor(iron);pet.getCollectionLog().loadForPlayer(pet);CoreRockMining.start(pet,iron.id,iron.x,iron.y,b->b==256?0:b==CoreRockMining.petDenominator(Rock.IRON,99)?0:b-1);tick(3);SkillsAuditCheck.clear(pet);ok(count(pet,13321)==1&&count(pet,440)==1,"Forced rock golem");restore(iron);
  System.out.println("CORE_MINING_LEVEL_MOVEMENT_HEIGHT_TOOL_REMOVAL_CANCEL_DEATH_FULL_INVENTORY_GEM_PRE_ROLL_BLANK_TABLE_AND_PET_OK");
 }
 static void debug(List<WorldObject> rows){
  WorldObject o=rows.stream().filter(v->v.x==3373&&v.y==9626&&v.height==1).findFirst().orElseThrow();Player p=actor(o);var region=p.getRegionProvider().get(o.x,o.y);System.out.println("CORE_CLIP_BEFORE "+region.getClip(o.x,o.y,o.height)+" solid="+ObjectDef.getObjectDef(o.id).solid());CoreRockMining.start(p,o.id,o.x,o.y,success(99));tick(3);SkillsAuditCheck.clear(p);System.out.println("CORE_CLIP_EMPTY "+region.getClip(o.x,o.y,o.height)+" solid="+ObjectDef.getObjectDef(Mineral.EMPTY_VEIN).solid());restore(o);System.out.println("CORE_CLIP_AFTER "+region.getClip(o.x,o.y,o.height));
 }
 public static void main(String[] args)throws Exception{try{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;Configuration.BONUS_SKILL_TIMER=Long.MAX_VALUE;io.xeros.model.cycleevent.CycleEventHandler.getSingleton().stopEvents(Boolean.FALSE);List<WorldObject> rows=nodes();if(args.length>0){debug(rows);System.exit(0);}tables();cycles(rows);bonuses(rows);guards(rows);System.out.println("CORE_MINING_ALL_CHECKS_PASSED");System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}

